question.text:
Xét xem kết quả của đoạn mã dưới đây là gì:
```cpp
int x = 10;

int *p = &x;

printf("%d", *(&x));
```

Đoạn code sau in ra gì???
```cpp
#include <iostream>
int main() {
  int R = 3, C = 4;

  int **mt = new int *[R];
  int *temp = new int[R * C];
  for (int i = 0; i < R; ++i) {
    mt[i] = temp;

    temp += C;
  }
  for (int i = 0; i < R * C; ++i) {
    mt[0][i] = i * 2;
  }
  int *ptr = mt[1] + 2;
  std::cout << *ptr << " " << mt[2][-1] << std::endl;
  delete[] mt[0];

  delete[] mt;

  return 0;
}
```

