Kết quả của chương trình là:
```cpp
#include <iostream>
using namespace std;
int main() {
  int a = 1, b = 2;

  auto func = [=, &a]() mutable {
    a += 10;
    b += 10;
    return a + b;
        
  };
  int c = func();

  cout << a << ", " << b << ", " << c;

  return 0;
}
```

